mapper.select:
SELECT id, incident_id, operational_period_id, duty_shift_id, marker_type, support_request_type, ST_AsEWKT(location) AS location, memo, occurred_at, created_by_account_id, police_phone_id, marker_source, status, version FROM marker WHERE incident_id = #{incidentId, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
AND operational_period_id = #{filters.opId, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
AND marker_type = #{filters.type}
AND status = #{filters.status}
AND status IN ('ACTIVE', 'UPDATED')
ORDER BY occurred_at ASC, id ASC

SELECT marker_id, id AS photo_id, status, version, content_type, size_bytes, attached_at FROM photo WHERE marker_id IN
#{markerId, typeHandler=com.surimap.config.mybatis.UuidTypeHandler}
AND status = 'ATTACHED' ORDER BY marker_id ASC, attached_at ASC, id ASC
